    53  v_int32 Hex::readUInt16(const char* buffer, v_uint16& value) {
    54    value = 0;
    55    for(v_uint32 i = 0; i < 4; i++){
    56      v_char8 a = static_cast<v_char8>(buffer[i]);
    57      if(a >= '0' && a <= '9') {
    58        value |= static_cast<v_uint16>((a - '0') << ((3 - i) << 2));
    59      } else if (a >= 'A' && a <= 'F') {
    60        value |= static_cast<v_uint16>((a - 'A' + 10) << ((3 - i) << 2));
    61      } else if (a >= 'a' && a <= 'f') {
    62        value |= static_cast<v_uint16>((a - 'a' + 10) << ((3 - i) << 2));
    63      } else {
    64        return ERROR_UNKNOWN_SYMBOL;
    65      }
    66    }
    67    return 0;
    68  }
    69
    70  v_int32 Hex::readUInt32(const char* buffer, v_uint32& value) {
    71    value = 0;
    72    for(v_uint32 i = 0; i < 8; i++){
    73      v_char8 a = static_cast<v_char8>(buffer[i]);
    74      if(a >= '0' && a <= '9') {
    75        value |= static_cast<v_uint32>(a - '0') << ((7 - i) << 2);
    76      } else if (a >= 'A' && a <= 'F') {
    77        value |= static_cast<v_uint32>(a - 'A' + 10) << ((7 - i) << 2);
    78      } else if (a >= 'a' && a <= 'f') {
    79        value |= static_cast<v_uint32>(a - 'a' + 10) << ((7 - i) << 2);
    80      } else {
    81        return ERROR_UNKNOWN_SYMBOL;
    82      }
    83    }
    84    return 0;
    85  }
