    87  void Hex::encode(data::stream::ConsistentOutputStream* stream,
    88                   const void* data, v_buff_size size,
    89                   const char* alphabet)
    90  {
    91    auto buffer = reinterpret_cast<const char*>(data);
    92    char oneByteBuffer[2];
    93    for(v_buff_size i = 0; i < size; i ++) {
    94      v_char8 c = static_cast<v_char8>(buffer[i]);
    95      v_char8 b1 = 0x0F & (c >> 4);
    96      v_char8 b2 = 0x0F & (c);
    97      oneByteBuffer[0] = alphabet[b1];
    98      oneByteBuffer[1] = alphabet[b2];
    99      stream->writeSimple(oneByteBuffer, 2);
   100    }
   101  }
