   103  oatpp::String Hex::encode(const oatpp::String& data, const char* alphabet) {
   104    oatpp::data::stream::BufferOutputStream ss(256);
   105    encode(&ss, data->data(), static_cast<v_buff_size>(data->size()), alphabet);
   106    return ss.toString();
   107  }
