   109  void Hex::decode(data::stream::ConsistentOutputStream* stream,
   110                   const void* data, v_buff_size size, bool allowSeparators)
   111  {
   112    auto buffer = reinterpret_cast<const char*>(data);
   113    v_char8 byte = 0;
   114    v_int32 shift = 4;
   115    for(v_buff_size i = 0; i < size; i ++) {
   116
   117      auto a = buffer[i];
   118
   119      if(a >= '0' && a <= '9') {
   120        byte |= static_cast<v_char8>((a - '0') << shift);
   121        shift -= 4;
   122      } else if (a >= 'A' && a <= 'F') {
   123        byte |= static_cast<v_char8>((a - 'A' + 10) << shift);
   124        shift -= 4;
   125      } else if (a >= 'a' && a <= 'f') {
   126        byte |= static_cast<v_char8>((a - 'a' + 10) << shift);
   127        shift -= 4;
   128      } else if(!allowSeparators) {
   129        throw DecodingError("Invalid Character");
   130      }
   131
   132      if(shift < 0) {
   133        stream->writeCharSimple(byte);
   134        byte = 0;
   135        shift = 4;
   136      }
   137
   138    }
   139
   140    if(shift != 4) {
   141      throw DecodingError("Invalid input data size");
   142    }
   143
   144  }
   145
   146  oatpp::String Hex::decode(const oatpp::String& data, bool allowSeparators) {
   147    oatpp::data::stream::BufferOutputStream ss(256);
   148    decode(&ss, data->data(), static_cast<v_buff_size>(data->size()), allowSeparators);
   149    return ss.toString();
   150  }
